 private void openGame(String id,boolean fresh){screen="game";catalogPage=GameCatalog.find(id).round/9;gameId=id;base(GameCatalog.find(id).title);GameRules state=new GameRules(GameCatalog.find(id));if(!fresh){try{state.restore(progress.load(id));}catch(IllegalArgumentException invalid){state=new GameRules(GameCatalog.find(id));}}paused=false;LinearLayout controls=row();Button pause=button("Pause",()->{paused=!paused;if(paused)gameView.pause();else gameView.resume();status.setText(paused?"Paused. Take a breath.":gameView.rules.message);});controls.addView(pause,new LinearLayout.LayoutParams(0,theme.dp(64),1));controls.addView(button("Replay",()->openGame(id,true)),new LinearLayout.LayoutParams(0,theme.dp(64),1));body.addView(controls);status=text(state.message,18,false);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(status);
  gameView=new GameView(this,state,theme,sound,wallet,new GameView.Listener(){public void changed(GameRules s){progress.save(s);status.setText(s.message);}public void completed(GameRules s){boolean first=progress.complete(s);status.setText(first?"You explored it! +1 star and +"+s.game.rewardCoins()+" coins.":"You explored it again! Your first-clear reward is saved.");}});HorizontalScrollView canvasScroll=new HorizontalScrollView(this);canvasScroll.setFillViewport(true);int canvasWidth=Math.max(theme.dp(320),getResources().getDisplayMetrics().widthPixels-theme.dp(24));FrameLayout stageFrame=new FrameLayout(this);stageFrame.setMinimumHeight(Math.round(canvasWidth*1000f/640));
  if(((android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion>=0x20000){final GameView target=gameView;final NativeStageSurface[]holder={null};NativeStageSurface stage=new NativeStageSurface(this,theme.dark,()->{target.stage(null);if(holder[0]!=null){holder[0].pauseStage();holder[0].setVisibility(View.GONE);}});holder[0]=stage;stageFrame.addView(stage,new FrameLayout.LayoutParams(-1,-1));gameView.stage(stage);}
  stageFrame.addView(gameView,new FrameLayout.LayoutParams(-1,-1));canvasScroll.addView(stageFrame,new ViewGroup.LayoutParams(canvasWidth,Math.round(canvasWidth*1000f/640)));body.addView(canvasScroll,new LinearLayout.LayoutParams(-1,-2));addButton("More games here",()->category(GameCatalog.find(id).kind));}
 private void shop(){screen="shop";gameId=null;base("My friend");wardrobeBalance=new LinearLayout(this);wardrobeBalance.setGravity(Gravity.CENTER);body.addView(wardrobeBalance);body.addView(friendPreview(),new LinearLayout.LayoutParams(-1,theme.dp(168)));wardrobeMessage=text("Pick a look for your friend",18,true);wardrobeMessage.setGravity(Gravity.CENTER);wardrobeMessage.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(wardrobeMessage);wardrobeGrid=GameUi.grid(this);body.addView(wardrobeGrid);refreshWardrobe();body.addView(text("Made yours through play. Coins stay in this app and have no cash value. No money purchases.",13,false));}
 private void refreshWardrobe(){wardrobeBalance.removeAllViews();wardrobeBalance.addView(GameUi.balance(this,theme,wallet.stars(),wallet.coins()));wardrobeGrid.removeAllViews();View[]looks=new View[PlayerWallet.SHOP.size()];for(int i=0;i<looks.length;i++){final PlayerWallet.Item item=PlayerWallet.SHOP.get(i);boolean owns=wallet.owns(item.id),selected=item.id.equals(wallet.equipped(item.category));int art=item.category.equals("skin")?0:item.id.equals("hat")?1:item.id.equals("bow")?2:3;String detail=selected?"Wearing now":owns?"Ready to wear":item.cost+" coins";looks[i]=GameUi.card(this,theme,item.name,detail,art,item.category.equals("skin")?item.color:wallet.skinColor(),false,selected,()->{sound.tap();String result=wallet.purchase(item.id);refreshWardrobe();wardrobeMessage.setText(result);if(previewStage!=null)previewStage.submit(friendFrame());if(friendFallback!=null)friendFallback.invalidate();});}GameUi.cells(wardrobeGrid,looks,2,theme,140);}
 private void parentGate(){String stored=getSharedPreferences("family",0).getString("pin_hash","");boolean setup=stored.isEmpty();LinearLayout form=new LinearLayout(this);form.setOrientation(1);EditText input=new EditText(this),confirmation=new EditText(this);for(EditText e:new EditText[]{input,confirmation}){e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(6)});e.setTextColor(theme.text);e.setHintTextColor(theme.text);e.setTextSize(22);e.setMinHeight(theme.dp(64));form.addView(e);}input.setHint(setup?"Create six-digit parent PIN":"Parent PIN");confirmation.setHint("Repeat parent PIN");confirmation.setVisibility(setup?View.VISIBLE:View.GONE);
  AlertDialog d=new AlertDialog.Builder(this).setTitle(setup?"Parent setup":"Parent space").setMessage("Ask a grown-up. PIN stays on this device.").setView(form).setPositiveButton("Continue",null).setNegativeButton("Back",null).create();d.setOnShowListener(v->{d.getWindow().setBackgroundDrawable(theme.panel(false));styleDialog(d);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{String pin=input.getText().toString();if(!pin.matches("[0-9]{6}")||(setup&&!pin.equals(confirmation.getText().toString()))){input.setError("Enter matching six-digit PINs.");return;}String salt=getSharedPreferences("family",0).getString("pin_salt","");if(setup){byte[]bytes=new byte[16];new SecureRandom().nextBytes(bytes);salt=hex(bytes);getSharedPreferences("family",0).edit().putString("pin_salt",salt).putString("pin_hash",hash(salt+pin)).apply();}else if(!MessageDigest.isEqual(hash(salt+pin).getBytes(java.nio.charset.StandardCharsets.UTF_8),stored.getBytes(java.nio.charset.StandardCharsets.UTF_8))){input.setError("Check your PIN with a grown-up.");return;}d.dismiss();parents();});});d.show();}
 private void styleDialog(AlertDialog d){View decor=d.getWindow().getDecorView();styleText(decor);}
 private void styleText(View v){if(v instanceof TextView){TextView t=(TextView)v;t.setTextColor(theme.text);t.setTypeface(theme.font(false));}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)styleText(((ViewGroup)v).getChildAt(i));}
 private static String hex(byte[]data){StringBuilder b=new StringBuilder();for(byte x:data)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 private static String hash(String value){try{return hex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private void parents(){screen="parent";gameId=null;base("Parent space");try{body.addView(text("Build "+getPackageManager().getPackageInfo(getPackageName(),0).versionName+" · OpenGL ES "+Integer.toHexString(((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion),15,false));}catch(android.content.pm.PackageManager.NameNotFoundException ignored){}walletLine();body.addView(text("1,200 modules across 20 original mechanics. First completion gives one star and fixed coins. Replay is always free. All progress stays on this device.",17,false));for(String mode:new String[]{"light","dark","system"})addButton("Theme: "+mode,()->{getSharedPreferences("family",0).edit().putString("theme",mode).apply();parents();});addButton("Sound: "+(getSharedPreferences("family",0).getBoolean("sound",true)?"on":"off"),()->{sound.setEnabled(!getSharedPreferences("family",0).getBoolean("sound",true));parents();});addButton("Reduced motion: "+(getSharedPreferences("family",0).getBoolean("reduce_motion",false)?"on":"off"),()->{getSharedPreferences("family",0).edit().putBoolean("reduce_motion",!getSharedPreferences("family",0).getBoolean("reduce_motion",false)).apply();parents();});addButton("Privacy policy",()->privacy());addButton("Reset local progress",()->resetDialog());body.addView(text("Take breaks together. The parent PIN is a local settings barrier, not proof of parental consent. It is not a child account. This native edition does not import the web edition profile.",17,false));}
 @Override protected void onPause(){if(visualMenu!=null)visualMenu.pause();if(previewStage!=null)previewStage.pauseStage();if(gameView!=null){progress.save(gameView.rules);gameView.pause();}sound.stop();if(screen.equals("parent"))home();super.onPause();}
